package com.company.skillplatform.artifact.application;import com.company.skillplatform.artifact.infrastructure.repository.SkillArtifactRepository;import com.company.skillplatform.skill.application.SkillService;import java.util.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ArtifactService{private final SkillArtifactRepository artifacts;private final SkillService skills;public ArtifactService(SkillArtifactRepository a,SkillService s){artifacts=a;skills=s;}@PreAuthorize("hasAuthority('skill:browse')")@Transactional(readOnly=true)public List<ArtifactView> list(Long versionId){skills.version(versionId);return artifacts.findByVersionIdAndStatus(versionId,"AVAILABLE").stream().map(a->new ArtifactView(a.getId(),a.getPlatform().getPlatformKey(),a.getOsType(),a.getArtifactType(),a.getFileName(),a.getSizeBytes(),a.getSha256(),a.getAdapterVersion())).toList();}public record ArtifactView(Long id,String platform,String osType,String artifactType,String fileName,long sizeBytes,String sha256,String adapterVersion){}}
